package com.nextaicommerce.platform.fba;
import java.util.*;import java.math.BigDecimal;import java.time.Instant;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import org.springframework.jdbc.core.JdbcTemplate;import tools.jackson.databind.ObjectMapper;import com.nextaicommerce.platform.receiving.InventoryRepository;
import static com.nextaicommerce.platform.fba.FbaInboundWorkflow.*;import static com.nextaicommerce.platform.fba.FbaChildDispatches.*;
class FbaChildDispatchesTest {
 final UUID tenant=UUID.randomUUID(),store=UUID.randomUUID(),planId=UUID.randomUUID(),warehouse=UUID.randomUUID(),item=UUID.randomUUID(),allocation=UUID.randomUUID(),reservation=UUID.randomUUID(),location=UUID.randomUUID(),user=UUID.randomUUID();final String actor="operator@example.test";final ObjectMapper json=new ObjectMapper();
 JdbcTemplate jdbc;FbaReplenishmentPlans plans;FbaChildDispatches service;Origin origin;
 @BeforeEach void setup(){jdbc=mock(JdbcTemplate.class);plans=spy(new FbaReplenishmentPlans(jdbc,json,mock(InventoryRepository.class)));service=spy(new FbaChildDispatches(plans,jdbc,json));doReturn(user).when(plans).actor(actor);origin=verifiedOrigin();doReturn(origin).when(service).origin(any(),eq(tenant),eq(store),any());doReturn(plan(Map.of())).when(plans).read(eq(tenant),eq(store),eq(planId),anyBoolean());doReturn(List.of(row(8,0,"ACTIVE"))).when(service).allocations(tenant,store,planId,warehouse);
  when(jdbc.queryForObject(startsWith("SELECT coalesce(sum(quantity),0) FROM inventory_ledger_entries"),eq(BigDecimal.class),any(Object[].class))).thenReturn(BigDecimal.TEN);
  when(jdbc.queryForObject(startsWith("SELECT coalesce(sum(quantity),0) FROM order_inventory_reservations"),eq(BigDecimal.class),any(Object[].class))).thenReturn(BigDecimal.valueOf(8));when(jdbc.queryForObject(startsWith("SELECT CASE WHEN EXISTS"),eq(String.class),any(Object[].class))).thenReturn("PART_DISPATCHED");
 }
 Origin verifiedOrigin(){var attempts=new HashMap<UUID,Attempt>();UUID placement=UUID.randomUUID(),transport=UUID.randomUUID();attempts.put(placement,new Attempt(placement,FbaInboundAdapter.Operation.CONFIRM_PLACEMENT,null,1,"placement",Status.SUCCEEDED,"remote-placement-op"));attempts.put(transport,new Attempt(transport,FbaInboundAdapter.Operation.CONFIRM_TRANSPORT,"child-A",1,"transport",Status.SUCCEEDED,"remote-transport-op"));return new Origin(new Scope(tenant,tenant,store,planId),warehouse,1,"verified-plan",attempts,Map.of("child-A",new Child("child-A",Map.of("PACK",1)),"child-B",new Child("child-B",Map.of("PACK",1))),Map.of(),List.of());}
 FbaReplenishmentPlans.Plan plan(Map<String,Object> checkpoint){return new FbaReplenishmentPlans.Plan(planId,"FBA001","ALLOCATED",1,3,checkpoint,List.of(),List.of());}
 Map<String,Object> row(int reserved,int dispatched,String status){var r=new HashMap<String,Object>();r.put("id",allocation);r.put("reservation_id",reservation);r.put("warehouse_id",warehouse);r.put("seller_sku","PACK");r.put("item",item);r.put("location_id",location);r.put("expiration_date",null);r.put("each_per_sku",4);r.put("quantity",8);r.put("dispatched",dispatched);r.put("reserved",reserved);r.put("reservation_status",status);r.put("unit_cost",BigDecimal.ONE);r.put("cost_currency","USD");return r;}
 Command command(String child,int units){return new Command(UUID.randomUUID(),1,warehouse,child,1,Map.of("PACK",units),"Confirmed actual dispatch");}
 Map<String,Object> saved(Recorded record){return Map.of("childDispatches",Map.of(warehouse+":"+record.shipment(),record));}
 @Test void firstDestinationChildConsumesOnlyItsShareWithoutNewReservation(){service.dispatch(tenant,store,planId,actor,command("child-A",1));verify(jdbc).update(eq("UPDATE order_inventory_reservations SET quantity=quantity-?,updated_at=now() WHERE tenant_id=? AND id=? AND fba_plan_id=?"),eq(4),eq(tenant),eq(reservation),eq(planId));verify(jdbc,never()).update(startsWith("INSERT INTO order_inventory_reservations"),any(Object[].class));var args=org.mockito.ArgumentCaptor.forClass(Object[].class);verify(jdbc).update(startsWith("INSERT INTO inventory_ledger_entries"),args.capture());assertEquals(-4,args.getValue()[5]);assertTrue(args.getValue()[12].toString().contains("child-A"));}
 @Test void secondChildUsesRemainingParentReservationWithoutDuplicatingFirst(){var first=new Recorded(warehouse,"child-A",1,Map.of("PACK",1),Map.of(allocation,4),"Truck",Instant.now());doReturn(plan(saved(first))).when(plans).read(eq(tenant),eq(store),eq(planId),anyBoolean());doReturn(List.of(row(4,4,"ACTIVE"))).when(service).allocations(tenant,store,planId,warehouse);service.dispatch(tenant,store,planId,actor,command("child-B",1));verify(jdbc).update(eq("UPDATE order_inventory_reservations SET status='SHIPPED',updated_at=now() WHERE tenant_id=? AND id=? AND fba_plan_id=?"),eq(tenant),eq(reservation),eq(planId));var args=org.mockito.ArgumentCaptor.forClass(Object[].class);verify(jdbc).update(startsWith("INSERT INTO inventory_ledger_entries"),args.capture());assertEquals(-4,args.getValue()[5]);}
 @Test void newRequestCannotRepeatAlreadyDispatchedChild(){var first=new Recorded(warehouse,"child-A",1,Map.of("PACK",1),Map.of(allocation,4),"Truck",Instant.now());doReturn(plan(saved(first))).when(plans).read(eq(tenant),eq(store),eq(planId),anyBoolean());assertDoesNotThrow(()->service.dispatch(tenant,store,planId,actor,command("child-A",1)));verify(jdbc,never()).update(startsWith("INSERT INTO inventory_ledger_entries"),any(Object[].class));}
 @Test void dispatchCannotExceedIssuedChildContents(){assertThrows(RuntimeException.class,()->service.dispatch(tenant,store,planId,actor,command("child-A",2)));verify(jdbc,never()).update(startsWith("INSERT INTO inventory_ledger_entries"),any(Object[].class));}
 @Test void demandCorrectionRestoresOnlyRecordedChildLayersAndKeepsUnsentUnitsReserved(){var previous=new Recorded(warehouse,"child-A",1,Map.of("PACK",1),Map.of(allocation,4),"Truck",Instant.now());doReturn(plan(saved(previous))).when(plans).read(eq(tenant),eq(store),eq(planId),anyBoolean());doReturn(List.of(row(4,4,"ACTIVE"))).when(service).allocations(tenant,store,planId,warehouse);service.correct(tenant,store,planId,actor,command("child-A",0));var args=org.mockito.ArgumentCaptor.forClass(Object[].class);verify(jdbc).update(startsWith("INSERT INTO inventory_ledger_entries"),args.capture());assertEquals(4,args.getValue()[5]);assertEquals("FBA_DISPATCH_CORRECTION",args.getValue()[4]);verify(jdbc).update(eq("UPDATE order_inventory_reservations SET quantity=quantity+?,updated_at=now() WHERE tenant_id=? AND id=? AND fba_plan_id=?"),eq(4),eq(tenant),eq(reservation),eq(planId));verify(jdbc,never()).update(contains("amazon_fba_shipment_items"),any(Object[].class));}
 @Test void correctingBackUpConsumesRestoredReservationWithoutChangingAmazonChild(){var previous=new Recorded(warehouse,"child-A",1,Map.of("PACK",0),Map.of(),"Actual lower",Instant.now());doReturn(plan(saved(previous))).when(plans).read(eq(tenant),eq(store),eq(planId),anyBoolean());service.correct(tenant,store,planId,actor,command("child-A",1));var args=org.mockito.ArgumentCaptor.forClass(Object[].class);verify(jdbc).update(startsWith("INSERT INTO inventory_ledger_entries"),args.capture());assertEquals(-4,args.getValue()[5]);assertEquals("FBA_DISPATCH_CORRECTION",args.getValue()[4]);}
 @Test void correctionCannotRestoreAnotherChildsLayer(){var previous=new Recorded(warehouse,"child-A",1,Map.of("PACK",1),Map.of(UUID.randomUUID(),4),"Truck",Instant.now());doReturn(plan(saved(previous))).when(plans).read(eq(tenant),eq(store),eq(planId),anyBoolean());assertThrows(RuntimeException.class,()->service.correct(tenant,store,planId,actor,command("child-A",0)));verify(jdbc,never()).update(startsWith("INSERT INTO inventory_ledger_entries"),any(Object[].class));}
 @Test void physicalShortageProtectsAllExistingReservations(){when(jdbc.queryForObject(startsWith("SELECT coalesce(sum(quantity),0) FROM inventory_ledger_entries"),eq(BigDecimal.class),any(Object[].class))).thenReturn(BigDecimal.valueOf(5));assertThrows(RuntimeException.class,()->service.dispatch(tenant,store,planId,actor,command("child-A",1)));verify(jdbc,never()).update(startsWith("INSERT INTO inventory_ledger_entries"),any(Object[].class));}
 @Test void receiptLayersNeverMultiplySkuComponentDemand(){var a=row(4,0,"ACTIVE");var b=new HashMap<>(row(4,0,"ACTIVE"));b.put("id",UUID.randomUUID());assertEquals(Map.of("PACK:"+item,4),requirements(List.of(a,b),Map.of("PACK",1)));}
 @Test void actualOriginValidationRequiresReconciledTransportAndExactScope(){doCallRealMethod().when(service).origin(any(),eq(tenant),eq(store),any());var p=plan(Map.of("inboundOrigins",Map.of(warehouse.toString(),new FbaInboundOrchestration.Checkpoint(origin,Map.of(),Map.of()))));p=new FbaReplenishmentPlans.Plan(p.id(),p.name(),p.status(),p.revision(),p.step(),p.checkpoint(),List.of(Map.of("warehouse_id",warehouse,"seller_sku","PACK","account_catalog_item_id",item,"each_per_sku",4,"quantity",8,"dispatched",0,"reservation_status","ACTIVE")),List.of());assertEquals(origin,service.origin(p,tenant,store,command("child-A",1)));var checked=p;assertThrows(RuntimeException.class,()->service.origin(checked,tenant,store,command("child-B",1)));}

 @Test void partialChildThenLaterIncreaseConsumesOnlyRemainingDelta(){
  origin=new Origin(origin.scope(),warehouse,1,origin.amazonPlanId(),origin.attempts(),Map.of("child-A",new Child("child-A",Map.of("PACK",2)),"child-B",new Child("child-B",Map.of("PACK",1))),Map.of(),List.of());doReturn(origin).when(service).origin(any(),eq(tenant),eq(store),any());
  var source=row(12,0,"ACTIVE");source.put("quantity",12);doReturn(List.of(source)).when(service).allocations(tenant,store,planId,warehouse);when(jdbc.queryForObject(startsWith("SELECT coalesce(sum(quantity),0) FROM inventory_ledger_entries"),eq(BigDecimal.class),any(Object[].class))).thenReturn(BigDecimal.valueOf(12));
  service.dispatch(tenant,store,planId,actor,command("child-A",1));
  var previous=new Recorded(warehouse,"child-A",1,Map.of("PACK",1),Map.of(allocation,4),"First partial dispatch",Instant.now());doReturn(plan(saved(previous))).when(plans).read(eq(tenant),eq(store),eq(planId),anyBoolean());source=row(8,4,"ACTIVE");source.put("quantity",12);doReturn(List.of(source)).when(service).allocations(tenant,store,planId,warehouse);service.dispatch(tenant,store,planId,actor,command("child-A",2));
  var writes=org.mockito.ArgumentCaptor.forClass(Object[].class);verify(jdbc,times(2)).update(startsWith("INSERT INTO inventory_ledger_entries"),writes.capture());assertEquals(List.of(-4,-4),writes.getAllValues().stream().map(a->a[5]).toList());verify(jdbc,never()).update(startsWith("INSERT INTO order_inventory_reservations"),any(Object[].class));
 }
 @Test void partialDispatchAllowsZeroSkuOnlyWhenAnotherSkuActuallyShips(){assertDoesNotThrow(()->validate(new Command(UUID.randomUUID(),1,warehouse,"child",1,Map.of("A",0,"B",1),"Partial actual dispatch"),false));assertThrows(RuntimeException.class,()->validate(new Command(UUID.randomUUID(),1,warehouse,"child",1,Map.of("A",0),"No actual dispatch"),false));}
 @Test void dispatchedFirstChildDoesNotStrandRemainingChildTransport(){
  service.dispatch(tenant,store,planId,actor,command("child-A",1));
  var checkpoint=new FbaInboundOrchestration.Checkpoint(origin,Map.of(),Map.of("placement",new FbaInboundOrchestration.Option("placement",FbaInboundAdapter.Operation.CONFIRM_PLACEMENT,1,Instant.now().plusSeconds(3600),BigDecimal.ZERO,"USD",List.of("child-A","child-B"),null,"{}"),"transport-B",new FbaInboundOrchestration.Option("transport-B",FbaInboundAdapter.Operation.CONFIRM_TRANSPORT,1,Instant.now().plusSeconds(3600),BigDecimal.ZERO,"USD",List.of("child-B"),"child-B","{}")));
  var carton=new FbaPackingManifest.Carton(UUID.randomUUID(),warehouse,"02.Pak",BigDecimal.TEN,BigDecimal.TEN,BigDecimal.ONE,"in",BigDecimal.ONE,"lb",true,Map.of("PACK",2));var packing=Map.of("validated",true,"cartons",List.of(carton),"transportByOrigin",Map.of(warehouse.toString(),Map.of("readyToShipAt",Instant.now().minusSeconds(86400).toString())));
  var allocationRow=new HashMap<>(row(4,4,"ACTIVE"));allocationRow.put("account_catalog_item_id",item);var partial=new FbaReplenishmentPlans.Plan(planId,"FBA001","PART_DISPATCHED",2,5,Map.of("packing",packing,"inboundOrigins",Map.of(warehouse.toString(),checkpoint)),List.of(allocationRow),List.of());doReturn(partial).when(plans).get(tenant,store,planId);
  var catalog=mock(com.nextaicommerce.platform.catalog.CatalogRepository.class);when(catalog.warehouseDetails(tenant,warehouse)).thenReturn(new com.nextaicommerce.platform.catalog.CatalogRepository.WarehouseDetails(warehouse,"Warehouse",false,"Street",null,"Tomball","TX","77377","US",List.of(new com.nextaicommerce.platform.catalog.CatalogRepository.WarehouseContact("Contact","2815550100")),"ACTIVE"));
  var payloads=new FbaInboundPayloads(plans,jdbc,catalog,mock(com.nextaicommerce.platform.orders.PackingPackageNames.class),json);assertEquals(Map.of("PACK",2),payloads.expectedSkuUnits(origin.scope(),warehouse));
  var generate=new FbaInboundOrchestration.Command(UUID.randomUUID(),2,FbaInboundAdapter.Operation.TRANSPORT_OPTIONS,null,null,false);assertThrows(IllegalStateException.class,()->payloads.build(origin.scope(),warehouse,checkpoint,generate));
  doReturn(partial).when(plans).read(eq(tenant),eq(store),eq(planId),eq(true));plans.checkpoint(tenant,store,planId,actor,new FbaReplenishmentPlans.Checkpoint(UUID.randomUUID(),2,2,null,Map.of(warehouse,new FbaReplenishmentPlans.TransportInput(Instant.now().plusSeconds(7200)))));
  var saved=org.mockito.ArgumentCaptor.forClass(Object[].class);verify(jdbc,times(2)).update(startsWith("UPDATE fba_replenishment_plans SET checkpoint="),saved.capture());var fresh=json.readValue(saved.getValue()[0].toString(),Map.class);var refreshed=new FbaReplenishmentPlans.Plan(planId,partial.name(),partial.status(),3,partial.step(),fresh,partial.allocations(),List.of());doReturn(refreshed).when(plans).get(tenant,store,planId);
  assertEquals(carton,json.treeToValue(json.valueToTree(fresh.get("packing")).path("cartons").get(0),FbaPackingManifest.Carton.class));assertEquals(checkpoint.origin(),FbaInboundCheckpoints.checkpoint(refreshed,origin.scope(),warehouse,json).origin());

  assertDoesNotThrow(()->payloads.build(origin.scope(),warehouse,checkpoint,new FbaInboundOrchestration.Command(UUID.randomUUID(),2,FbaInboundAdapter.Operation.TRANSPORT_OPTIONS,null,null,false)));
  var confirm=new FbaInboundOrchestration.Command(UUID.randomUUID(),2,FbaInboundAdapter.Operation.CONFIRM_TRANSPORT,"child-B","transport-B",true);assertEquals("child-B",json.readTree(payloads.build(origin.scope(),warehouse,checkpoint,confirm)).path("transportationSelections").get(0).path("shipmentId").asText());assertDoesNotThrow(()->payloads.build(origin.scope(),warehouse,checkpoint,confirm));
  verify(jdbc,times(1)).update(startsWith("INSERT INTO inventory_ledger_entries"),any(Object[].class));verify(jdbc,never()).update(startsWith("INSERT INTO order_inventory_reservations"),any(Object[].class));
  var badOrigin=new Origin(origin.scope(),warehouse,1,origin.amazonPlanId(),origin.attempts(),Map.of("child-B",new Child("child-B",Map.of("PACK",1))),Map.of(),List.of());var bad=new FbaInboundOrchestration.Checkpoint(badOrigin,Map.of(),checkpoint.options());assertThrows(IllegalStateException.class,()->payloads.build(origin.scope(),warehouse,bad,confirm));
 }
}
